mapper.select:
SELECT id, post_id, created_at
FROM conversations
WHERE id = #{id}

SELECT c.id
FROM conversations c
JOIN conversation_participants p1 ON p1.conversation_id = c.id AND p1.user_id = #{me}
JOIN conversation_participants p2 ON p2.conversation_id = c.id AND p2.user_id = #{peer}
WHERE c.post_id = #{postId}
LIMIT 1

SELECT c.id AS conversation_id, c.post_id,
       u.id AS peer_id, u.nickname AS peer_nickname, u.avatar AS peer_avatar
FROM conversations c
JOIN conversation_participants cp_me ON cp_me.conversation_id = c.id AND cp_me.user_id = #{userId}
JOIN conversation_participants cp_peer ON cp_peer.conversation_id = c.id AND cp_peer.user_id <> #{userId}
JOIN users u ON u.id = cp_peer.user_id
ORDER BY c.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT c.id AS conversation_id, c.post_id,
       u.id AS peer_id, u.nickname AS peer_nickname, u.avatar AS peer_avatar
FROM conversations c
JOIN conversation_participants cp_me ON cp_me.conversation_id = c.id AND cp_me.user_id = #{userId}
JOIN conversation_participants cp_peer ON cp_peer.conversation_id = c.id AND cp_peer.user_id <> #{userId}
JOIN users u ON u.id = cp_peer.user_id
WHERE c.id = #{conversationId}
